{
  "items": [
    {
      "name": "LinearIndependent.rank_matrix",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Rank",
      "kind": "theorem",
      "type": "∀ {m : Type um} {n : Type un} {R : Type uR} [inst : Fintype n] [inst_1 : Field R] [inst_2 : Fintype m]\n  {M : Matrix m n R}, LinearIndependent R M.row → M.rank = Fintype.card m"
    },
    {
      "name": "Matrix.rank_of_isUnit",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Rank",
      "kind": "theorem",
      "type": "∀ {n : Type un} {R : Type uR} [inst : Fintype n] [inst_1 : CommRing R] [Nontrivial R] [inst_3 : DecidableEq n]\n  (A : Matrix n n R), IsUnit A → A.rank = Fintype.card n"
    },
    {
      "name": "Matrix.rank_eq_finrank_span_row",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Rank",
      "kind": "theorem",
      "type": "∀ {m : Type um} {n : Type un} {R : Type uR} [inst : Fintype n] [inst_1 : Field R] [Finite m] (A : Matrix m n R),\n  A.rank = Module.finrank R ↥(Submodule.span R (Set.range A.row))"
    },
    {
      "name": "Matrix.rank_unit",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Rank",
      "kind": "theorem",
      "type": "∀ {n : Type un} {R : Type uR} [inst : Fintype n] [inst_1 : CommRing R] [Nontrivial R] [inst_3 : DecidableEq n]\n  (A : (Matrix n n R)ˣ), (↑A).rank = Fintype.card n"
    },
    {
      "name": "rank_matrix_module",
      "module_name": "Mathlib.LinearAlgebra.Dimension.Constructions",
      "kind": "theorem",
      "type": "∀ (R : Type u) (M : Type v) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] [StrongRankCondition R]\n  [Module.Free R M] (m : Type w) (n : Type w') [Finite m] [Finite n],\n  Module.rank R (Matrix m n M) =\n    Cardinal.lift.{max v w', w} (Cardinal.mk m) * Cardinal.lift.{max v w, w'} (Cardinal.mk n) *\n      Cardinal.lift.{max w w', v} (Module.rank R M)"
    }
  ]
}
